// Writes demos/registry.ts: one static import per demo file, keyed "<slug>/<example>".
import { readdirSync, writeFileSync } from 'node:fs';

const root = new URL('../demos/', import.meta.url);
const names = readdirSync(root, { withFileTypes: true })
  .filter((entry) => entry.isDirectory())
  .flatMap((dir) => readdirSync(new URL(`${dir.name}/`, root)).filter((file) => file.endsWith('.tsx')).map((file) => `${dir.name}/${file.slice(0, -4)}`))
  .sort();
const id = (name) => `Demo${names.indexOf(name)}`;
const lines = [
  '// Generated by scripts/registry.mjs. Do not edit.',
  "import type { ComponentType } from 'react';",
  ...names.map((name) => `import ${id(name)} from './${name}';`),
  '',
  'export const registry: Record<string, ComponentType> = {',
  ...names.map((name) => `  '${name}': ${id(name)},`),
  '};',
  '',
];
writeFileSync(new URL('registry.ts', root), lines.join('\n'));
console.log(`demos/registry.ts: ${names.length} demos`);
